test "todo: the schema documents BOTH forms, so the model knows the patch exists" {
    // A capability that is not in the schema does not get used — the lesson the
    // `task` tool taught. `update` in the schema with no explanation is worse: the
    // model has to guess whether indices are 0-based or 1-based.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const v = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), toolsJson(), .{}) catch
        return error.BadSchema;

    for (v.array.items) |item| {
        const fn_obj = item.object.get("function").?.object;
        if (!std.mem.eql(u8, fn_obj.get("name").?.string, "todo")) continue;
        const desc = fn_obj.get("description").?.string;
        for ([_][]const u8{ "update", "remove", "add", "1-BASED" }) |needle| {
            if (std.mem.indexOf(u8, desc, needle) == null) {
                std.debug.print("the todo description does not mention {s}\n", .{needle});
                return error.SchemaIncomplete;
            }
        }
        // And the parameters really expose them, not only the prose.
        const params = fn_obj.get("parameters").?.object;
        const props = params.get("properties").?.object;
        for ([_][]const u8{ "items", "update", "remove", "add" }) |k| {
            if (props.get(k) == null) return error.SchemaIncomplete;
        }
        // None of them is REQUIRED: a patch and a replacement are both complete on
        // their own, and requiring one of them would forbid the other.
        if (params.get("required") != null) return error.SchemaTooStrict;
        return;
    }
    return error.NoTodo;
}

test "the read description says a picture arrives as an IMAGE, not as bytes" {
    // Measured: asked to look at a PNG, the model ran `bash` with `strings` and
    // reported "PNG, IHDR, IDAT, IEND" — the magic bytes, not the picture. The
    // capability existed and was not reached for, which is the failure this whole
    // feature was at risk of repeating.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const v = std.json.parseFromSliceLeaky(std.json.Value, arena_state.allocator(), toolsJson(), .{}) catch
        return error.BadSchema;
    for (v.array.items) |item| {
        const fn_obj = item.object.get("function").?.object;
        if (!std.mem.eql(u8, fn_obj.get("name").?.string, "read")) continue;
        const desc = fn_obj.get("description").?.string;
        // "IMAGE" and not "image": the description shouts it on purpose, and a
        // test that matches the lowercase form fails on the word being right.
        for ([_][]const u8{ "PNG", "IMAGE", "never as bytes" }) |n| {
            if (std.mem.indexOf(u8, desc, n) == null) {
                std.debug.print("the read description does not say {s}\n", .{n});
                return error.SchemaIncomplete;
            }
        }
        return;
    }
    return error.NoRead;
}

test "check: a FAILED build is never reported as 'no type errors'" {
    // Measured, and it is the dangerous direction. A `build.zig` that panics prints
    // a source location and `thread N panic: object files have no standard
    // installation procedure` — neither is `file:line: error:`, so the diagnostic
    // scan found nothing and the tool answered **"no type errors"** while the build
    // had exited 2 with a stack trace.
    //
    // A check that fails and reports success is worse than no check: the model
    // reads "no type errors" and carries on editing a project whose build does not
    // even run.
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var reg = bgproc.Registry{};
    defer reg.deinit(undefined, std.testing.allocator);
    reg.slots[0] = .{ .state = .finished, .id = 7, .exit = 2 };
    try reg.slots[0].buf.appendSlice(
        std.testing.allocator,
        "/usr/lib/zig/std/Build/Step/InstallArtifact.zig:64:32: thread 508062 panic: object files have no standard installation procedure\n",
    );

    const out = try check_tool.report(arena, &reg, 7);
    try std.testing.expect(std.mem.indexOf(u8, out, "no type errors") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "FAILED") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "exit 2") != null);
    // And the panic is in there, because that is what the user has to read.
    try std.testing.expect(std.mem.indexOf(u8, out, "panic") != null);
    try std.testing.expect(std.mem.indexOf(u8, out, "Do NOT treat this as a passing build") != null);
}

test "check: a PASSING build with no diagnostics says so, and says nothing scary" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
